// ─── File: src/main/java/com/bank/loan/service/EligibilityService.java ───
package com.bank.loan.service;

import com.bank.loan.dto.EligibilityReport;
import com.bank.loan.model.Customer;
import com.bank.loan.repository.CustomerRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Predicate;
import java.util.stream.Collectors;
import java.util.stream.Stream;

@Service
@RequiredArgsConstructor
@Slf4j
public class EligibilityService {

    private final CustomerRepository customerRepo;

    @Value("${eligibility.min-credit-score:650}")
    private int minCreditScore;

    @Value("${eligibility.min-annual-income:500000}")
    private BigDecimal minIncome;

    @Value("${eligibility.max-existing-loans:3}")
    private int maxLoans;

    // ═══ DEMO 1: LAZINESS — nothing executes until terminal ═══
    @Transactional(readOnly = true)
    public EligibilityReport demonstrateLaziness() {
        List<Customer> customers = customerRepo.findAll();
        AtomicInteger filterCount = new AtomicInteger(0);
        AtomicInteger mapCount = new AtomicInteger(0);
        List<String> processingLog = Collections.synchronizedList(new ArrayList<>());

        // BUILD pipeline — NO execution:
        Stream<String> pipeline = customers.stream()
            .filter(c -> {
                int n = filterCount.incrementAndGet();
                processingLog.add("FILTER #" + n + ": " + c.getName()
                    + " (score=" + c.getCreditScore() + ")");
                return c.getCreditScore() >= minCreditScore;
            })
            .map(c -> {
                int n = mapCount.incrementAndGet();
                processingLog.add("MAP #" + n + ": " + c.getName() + " → eligible");
                return c.getName();
            });

        // AT THIS POINT: filterCount=0, mapCount=0
        // NOTHING has executed! Pipeline is just a description.
        processingLog.add("═══ BEFORE TERMINAL: filters=" + filterCount.get()
            + ", maps=" + mapCount.get() + " (both ZERO!) ═══");

        // NOW trigger with terminal:
        List<String> eligible = pipeline.toList();

        processingLog.add("═══ AFTER TERMINAL: filters=" + filterCount.get()
            + ", maps=" + mapCount.get() + " ═══");

        return new EligibilityReport("LAZINESS_DEMO", customers.size(),
            filterCount.get(), filterCount.get() + mapCount.get(),
            "Before terminal: 0 filters, 0 maps. After terminal: "
                + filterCount.get() + " filters, " + mapCount.get() + " maps.",
            eligible, processingLog);
    }

    // ═══ DEMO 2: SHORT-CIRCUIT — findFirst stops early ═══
    @Transactional(readOnly = true)
    public EligibilityReport demonstrateShortCircuit() {
        List<Customer> customers = customerRepo.findAll();
        AtomicInteger pullCount = new AtomicInteger(0);
        List<String> processingLog = Collections.synchronizedList(new ArrayList<>());

        // findFirst: stops after first eligible customer
        Optional<String> first = customers.stream()
            .peek(c -> {
                int n = pullCount.incrementAndGet();
                processingLog.add("PULL #" + n + ": " + c.getName());
            })
            .filter(c -> {
                boolean pass = c.getCreditScore() >= minCreditScore
                    && c.getAnnualIncome().compareTo(minIncome) >= 0
                    && c.getExistingLoans() < maxLoans;
                processingLog.add("  CHECK: score=" + c.getCreditScore()
                    + " income=" + c.getAnnualIncome()
                    + " loans=" + c.getExistingLoans()
                    + " → " + (pass ? "ELIGIBLE (Recommended) " : "REJECTED (Avoid) "));
                return pass;
            })
            .map(Customer::getName)
            .findFirst();  // SHORT-CIRCUIT!

        processingLog.add("═══ STOPPED after " + pullCount.get()
            + " of " + customers.size() + " customers ═══");

        return new EligibilityReport("SHORT_CIRCUIT (findFirst)",
            customers.size(), pullCount.get(), pullCount.get(),
            "Processed " + pullCount.get() + "/" + customers.size()
                + " — stopped at first eligible: " + first.orElse("none"),
            first.map(List::of).orElse(List.of()), processingLog);
    }

    // ═══ DEMO 3: LIMIT — short-circuit intermediate ═══
    @Transactional(readOnly = true)
    public EligibilityReport demonstrateLimit(int n) {
        List<Customer> customers = customerRepo.findAll();
        AtomicInteger pullCount = new AtomicInteger(0);
        List<String> processingLog = Collections.synchronizedList(new ArrayList<>());

        Predicate<Customer> isEligible = c ->
            c.getCreditScore() >= minCreditScore
            && c.getAnnualIncome().compareTo(minIncome) >= 0
            && c.getExistingLoans() < maxLoans;

        List<String> topN = customers.stream()
            .peek(c -> processingLog.add("PULL #" + pullCount.incrementAndGet()
                + ": " + c.getName()))
            .filter(c -> {
                boolean pass = isEligible.test(c);
                processingLog.add("  → " + (pass ? "ELIGIBLE (Recommended) " : "REJECTED (Avoid) "));
                return pass;
            })
            .map(Customer::getName)
            .limit(n)  // SHORT-CIRCUIT INTERMEDIATE: stop after n eligible
            .toList();

        processingLog.add("═══ limit(" + n + "): pulled " + pullCount.get()
            + " of " + customers.size() + " to find " + n + " eligible ═══");

        return new EligibilityReport("LIMIT(" + n + ")",
            customers.size(), pullCount.get(), pullCount.get(),
            "limit(" + n + "): pulled " + pullCount.get()
                + " customers to find " + n + " eligible",
            topN, processingLog);
    }

    // ═══ DEMO 4: FUSION — filter+map per element, not per operation ═══
    @Transactional(readOnly = true)
    public EligibilityReport demonstrateFusion() {
        List<Customer> customers = customerRepo.findAll();
        List<String> processingLog = Collections.synchronizedList(new ArrayList<>());

        List<String> eligible = customers.stream()
            .peek(c -> processingLog.add("[ENTER] " + c.getName()))
            .filter(c -> {
                boolean pass = c.getCreditScore() >= minCreditScore;
                processingLog.add("  [FILTER-1 credit] " + c.getName()
                    + " score=" + c.getCreditScore() + " → " + (pass ? "PASS" : "DROP"));
                return pass;
            })
            .filter(c -> {
                boolean pass = c.getAnnualIncome().compareTo(minIncome) >= 0;
                processingLog.add("  [FILTER-2 income] " + c.getName()
                    + " income=" + c.getAnnualIncome() + " → " + (pass ? "PASS" : "DROP"));
                return pass;
            })
            .map(c -> {
                processingLog.add("  [MAP] " + c.getName() + " → eligible DTO");
                return c.getName() + " (score=" + c.getCreditScore() + ")";
            })
            .peek(name -> processingLog.add("[EXIT] " + name))
            .toList();

        // Log proves: ENTER→FILTER1→FILTER2→MAP→EXIT per customer
        // NOT: FILTER1 all → FILTER2 all → MAP all!
        processingLog.add("═══ FUSION: each customer went through ALL ops before next ═══");

        return new EligibilityReport("FUSION_DEMO",
            customers.size(), customers.size(), customers.size() * 2,
            "Fused: filter1→filter2→map per customer, not filter1-all→filter2-all→map-all",
            eligible, processingLog);
    }
}
