    @GetMapping("/laziness")
    public EligibilityReport laziness() {
        return eligibilityService.demonstrateLaziness();
    }

    @GetMapping("/short-circuit")
    public EligibilityReport shortCircuit() {
        return eligibilityService.demonstrateShortCircuit();
    }

    @GetMapping("/limit/{n}")
    public EligibilityReport limit(@PathVariable int n) {
        return eligibilityService.demonstrateLimit(n);
    }

    @GetMapping("/fusion")
    public EligibilityReport fusion() {
        return eligibilityService.demonstrateFusion();
    }
}
