// ─── File: src/test/java/com/bank/loan/service/LazinessProofTest.java ───
package com.bank.loan.service;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.stream.Stream;
import static org.assertj.core.api.Assertions.*;

class LazinessProofTest {

    // ═══ PROOF 1: Intermediate ops do NOTHING until terminal ═══
    @Test
    void intermediateOpsAreLazyUntilTerminal() {
        AtomicInteger filterCalls = new AtomicInteger(0);
        AtomicInteger mapCalls = new AtomicInteger(0);

        Stream<String> pipeline = List.of("A", "B", "C").stream()
                .filter(s -> { filterCalls.incrementAndGet();
                return true; })
                .map(s -> { mapCalls.incrementAndGet();
                return s.toLowerCase(); });

        // NO terminal yet → ZERO execution
        assertThat(filterCalls.get()).isZero();
        assertThat(mapCalls.get()).isZero();

        // Terminal triggers ALL:
        pipeline.toList();
        assertThat(filterCalls.get()).isEqualTo(3);
        assertThat(mapCalls.get()).isEqualTo(3);
    }

    // ═══ PROOF 2: findFirst short-circuits ═══
    @Test
    void findFirstStopsAfterMatch() {
        AtomicInteger pulls = new AtomicInteger(0);

        Optional<String> result = List.of("low", "low", "HIGH", "HIGH", "HIGH").stream()
            .peek(s -> pulls.incrementAndGet())
            .filter(s -> s.equals("HIGH"))
            .findFirst();

        assertThat(result).contains("HIGH");
        assertThat(pulls.get()).isEqualTo(3);  // stopped at index 2, not 4!
    }

    // ═══ PROOF 3: limit short-circuits ═══
    @Test
    void limitStopsAfterNElements() {
        AtomicInteger pulls = new AtomicInteger(0);

        List<String> result = List.of("A", "B", "C", "D", "E").stream()
            .peek(s -> pulls.incrementAndGet())
            .limit(3)
            .toList();

        assertThat(result).containsExactly("A", "B", "C");
        assertThat(pulls.get()).isEqualTo(3);  // D and E never pulled!
    }

    // ═══ PROOF 4: anyMatch short-circuits on first true ═══
    @Test
    void anyMatchStopsOnFirstTrue() {
        AtomicInteger checks = new AtomicInteger(0);

        boolean found = List.of(100, 200, 750, 400, 900).stream()
            .peek(n -> checks.incrementAndGet())
            .anyMatch(n -> n >= 700);

        assertThat(found).isTrue();
        assertThat(checks.get()).isEqualTo(3);  // stopped at 750, never checked 400, 900
    }

    // ═══ PROOF 5: allMatch short-circuits on first false ═══
    @Test
    void allMatchStopsOnFirstFalse() {
        AtomicInteger checks = new AtomicInteger(0);

        boolean allHigh = List.of(750, 800, 490, 820, 900).stream()
            .peek(n -> checks.incrementAndGet())
            .allMatch(n -> n >= 650);

        assertThat(allHigh).isFalse();
        assertThat(checks.get()).isEqualTo(3);  // stopped at 490, never checked 820, 900
    }

    // ═══ PROOF 6: Fusion — ops execute per-element, not per-operation ═══
    @Test
    void fusionProcessesPerElementNotPerOperation() {
        List<String> executionOrder = new ArrayList<>();

        List.of("CUST-A", "CUST-B", "CUST-C").stream()
            .peek(c -> executionOrder.add("FILTER:" + c))
            .filter(c -> !c.equals("CUST-B"))
            .peek(c -> executionOrder.add("MAP:" + c))
            .map(String::toLowerCase)
            .toList();

        // FUSED order: each customer through all ops before next
        assertThat(executionOrder).containsExactly(
            "FILTER:CUST-A", "MAP:CUST-A",     // A: filter→map
            "FILTER:CUST-B",                    // B: filter drops (no map!)
            "FILTER:CUST-C", "MAP:CUST-C"       // C: filter→map
        );
        // NOT: FILTER:A, FILTER:B, FILTER:C, MAP:A, MAP:C (that would be multi-pass)
    }
}
